from .errors import AccessDenied, InvalidRequest

def dispatch(job, store):
    if job.operation == "preview":
        if job.permit.operation != "read":
            raise AccessDenied("read permit required")
        return store.read(job.tenant, job.key)
    if job.operation == "archive":
        if job.permit.operation != "export":
            raise AccessDenied("export permit required")
        return {"tenant": job.tenant, "rows": store.export(job.tenant)}
    raise InvalidRequest("unsupported job")

from dataclasses import dataclass
from .errors import AccessDenied

@dataclass(frozen=True)
class Permit:
    subject: str
    tenant: str
    operation: str

def require_scope(identity, operation):
    if operation not in identity.scopes:
        raise AccessDenied("scope required")
    return Permit(identity.subject, identity.tenant, operation)

def require_tenant(identity, tenant):
    if tenant != identity.tenant:
        raise AccessDenied("tenant mismatch")

def require_owner(identity):
    if identity.role != "owner":
        raise AccessDenied("owner required")

def authorize(identity, operation, owner_only=False):
    permit = require_scope(identity, operation)
    if owner_only:
        require_owner(identity)
    return permit

from copy import deepcopy
from .seed import DOCUMENTS, EXPORT_ROWS
from .errors import NotFound

class Store:
    def __init__(self):
        self.documents = deepcopy(DOCUMENTS)
        self.exports = deepcopy(EXPORT_ROWS)

    def read(self, tenant, key):
        record = self.documents.get((tenant, key))
        if record is None:
            raise NotFound("document")
        return deepcopy(record)

    def export(self, tenant):
        if tenant not in self.exports:
            raise NotFound("tenant")
        return deepcopy(self.exports[tenant])

    def purge(self, tenant, key):
        if (tenant, key) not in self.documents:
            raise NotFound("document")
        del self.documents[(tenant, key)]
        return {"removed": key}
